begin;
create view public.engineering_contract_financial_summary with(security_invoker=true) as with ad as(select a.tenant_id,a.company_id,a.contract_id,sum(case when a.status in('approved','active') then coalesce(a.stated_value,x.lines_value,0) else 0 end) addenda_net from public.contract_addenda a left join(select tenant_id,company_id,addendum_id,sum(line_total) lines_value from public.contract_addendum_lines group by tenant_id,company_id,addendum_id)x on x.tenant_id=a.tenant_id and x.company_id=a.company_id and x.addendum_id=a.id group by a.tenant_id,a.company_id,a.contract_id),meas as(select m.tenant_id,m.company_id,m.contract_id,sum(case when m.status in('closed','approved') then fs.gross_amount else 0 end) measured_gross,sum(case when m.status in('closed','approved') then fs.retained_amount else 0 end) retained_amount,sum(case when m.status in('closed','approved') then fs.net_amount else 0 end) measured_net from public.measurements m join public.measurement_financial_summary fs on fs.tenant_id=m.tenant_id and fs.company_id=m.company_id and fs.measurement_id=m.id group by m.tenant_id,m.company_id,m.contract_id) select c.tenant_id,c.company_id,c.work_id,c.id contract_id,c.contract_number,c.status,c.base_value original_contract_value,coalesce(ad.addenda_net,0)::numeric(18,2) addenda_net,(c.base_value+coalesce(ad.addenda_net,0))::numeric(18,2) updated_contract_value,coalesce(meas.measured_gross,0)::numeric(18,2) measured_gross,coalesce(meas.retained_amount,0)::numeric(18,2) retained_amount,coalesce(meas.measured_net,0)::numeric(18,2) measured_net,(c.base_value+coalesce(ad.addenda_net,0)-coalesce(meas.measured_gross,0))::numeric(18,2) gross_balance,case when c.base_value+coalesce(ad.addenda_net,0)>0 then round(coalesce(meas.measured_gross,0)*100/(c.base_value+coalesce(ad.addenda_net,0)),2) else 0 end measured_percent from public.engineering_contracts c left join ad on ad.tenant_id=c.tenant_id and ad.company_id=c.company_id and ad.contract_id=c.id left join meas on meas.tenant_id=c.tenant_id and meas.company_id=c.company_id and meas.contract_id=c.id;
create view public.engineering_work_dashboard with(security_invoker=true) as with cf as(select tenant_id,company_id,work_id,sum(original_contract_value) original_contract_value,sum(addenda_net) addenda_net,sum(updated_contract_value) updated_contract_value,sum(measured_gross) measured_gross,sum(retained_amount) retained_amount,sum(measured_net) measured_net,sum(gross_balance) gross_balance from public.engineering_contract_financial_summary group by tenant_id,company_id,work_id),prod as(select p.tenant_id,p.company_id,p.work_id,sum(e.executed_quantity) production_quantity,coalesce(sum(e.production_value),0) production_value from public.engineering_production_periods p join public.engineering_production_entries e on e.tenant_id=p.tenant_id and e.company_id=p.company_id and e.production_period_id=p.id group by p.tenant_id,p.company_id,p.work_id) select w.tenant_id,w.company_id,w.id work_id,w.name work_name,w.status work_status,coalesce(cf.original_contract_value,0)::numeric(18,2) original_contract_value,coalesce(cf.addenda_net,0)::numeric(18,2) addenda_net,coalesce(cf.updated_contract_value,0)::numeric(18,2) updated_contract_value,coalesce(cf.measured_gross,0)::numeric(18,2) measured_gross,coalesce(cf.retained_amount,0)::numeric(18,2) retained_amount,coalesce(cf.measured_net,0)::numeric(18,2) measured_net,coalesce(cf.gross_balance,0)::numeric(18,2) gross_balance,case when coalesce(cf.updated_contract_value,0)>0 then round(coalesce(cf.measured_gross,0)*100/cf.updated_contract_value,2) else 0 end measured_percent,coalesce(prod.production_quantity,0)::numeric(18,6) production_quantity,coalesce(prod.production_value,0)::numeric(18,2) production_value from public.works w left join cf on cf.tenant_id=w.tenant_id and cf.company_id=w.company_id and cf.work_id=w.id left join prod on prod.tenant_id=w.tenant_id and prod.company_id=w.company_id and prod.work_id=w.id;
create view public.engineering_measurement_monthly_report with(security_invoker=true) as select m.tenant_id,m.company_id,c.work_id,m.contract_id,m.id measurement_id,m.competence,m.status,fs.gross_amount,fs.retained_amount,fs.net_amount from public.measurements m join public.engineering_contracts c on c.tenant_id=m.tenant_id and c.company_id=m.company_id and c.id=m.contract_id join public.measurement_financial_summary fs on fs.tenant_id=m.tenant_id and fs.company_id=m.company_id and fs.measurement_id=m.id;
commit;